<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {account,plex} from './plex-client';
import {getLearning,putLearning} from './learning-store';
import {registerLearningFlush} from './learning-flush';
import type {SensorHandle} from './input-sensors';
const props=defineProps<{sectionId:string;sectionTitle:string;suspended:boolean}>();
const emit=defineEmits<{open:[value:boolean];dictating:[value:boolean];login:[]}>();
const opened=ref(false),position=ref({x:0,y:0}),viewport=ref({w:1200,h:800}),ready=ref(false),busy=ref(false),draft=ref(''),error=ref(''),voiceStatus=ref(''),partial=ref(''),listening=ref(false),volume=ref(0),messages=ref<{role:'user'|'assistant';content:string;source?:string}[]>([]),log=ref<HTMLElement>(),input=ref<HTMLTextAreaElement>(),pet=ref<HTMLButtonElement>();
const bubble=computed(()=>{
 const {w,h}=viewport.value,{x,y}=position.value;
 const above=y-20,below=h-y-168,placeAbove=above>=below;
 const height=Math.min(520,h-16,Math.max(Math.min(260,h-16),placeAbove?above:below));
 return {left:Math.max(8,Math.min(x-270,w-Math.min(380,w-16)-8))+'px',top:Math.max(8,Math.min(placeAbove?y-height-12:y+160,h-height-8))+'px',height:height+'px'};
});
let dragging:{x:number;y:number;px:number;py:number}|undefined,moved=false,request:AbortController|undefined,serial=0,speechAbort:AbortController|undefined,speech:SensorHandle|undefined,speechSeq=0,lastResult=0,saveTimer:ReturnType<typeof setTimeout>|undefined,disposed=false;
function clamp(){viewport.value={w:innerWidth,h:innerHeight};position.value.x=Math.max(8,Math.min(position.value.x,innerWidth-112));position.value.y=Math.max(8,Math.min(position.value.y,innerHeight-224));}
function dragStart(e:PointerEvent){if(e.button!==0)return;moved=false;dragging={x:e.clientX,y:e.clientY,px:position.value.x,py:position.value.y};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);}
function dragMove(e:PointerEvent){if(!dragging)return;const dx=e.clientX-dragging.x,dy=e.clientY-dragging.y;if(Math.hypot(dx,dy)>5)moved=true;if(!moved)return;position.value={x:dragging.px+dx,y:dragging.py+dy};clamp();}
function dragEnd(e:PointerEvent){dragging=undefined;const target=e.currentTarget as HTMLElement;if(target.hasPointerCapture(e.pointerId))target.releasePointerCapture(e.pointerId);if(moved)void putLearning('pet:position',position.value).catch(()=>error.value='位置保存失败');}
function toggle(){if(moved){moved=false;return;}opened.value=!opened.value;emit('open',opened.value);if(opened.value)nextTick(()=>input.value?.focus({preventScroll:true}));else{stopSpeech();cancel();pet.value?.focus({preventScroll:true});}}
function close(){if(opened.value){opened.value=false;emit('open',false);stopSpeech();cancel();pet.value?.focus({preventScroll:true});}}
function petKey(e:KeyboardEvent){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();position.value.x+=e.key==='ArrowLeft'?-16:e.key==='ArrowRight'?16:0;position.value.y+=e.key==='ArrowUp'?-16:e.key==='ArrowDown'?16:0;clamp();void putLearning('pet:position',position.value).catch(()=>{});}}
async function saveDraft(){clearTimeout(saveTimer);if(!ready.value)return;await putLearning('pet:draft',{text:draft.value}).catch(()=>error.value='草稿保存失败，关闭前请复制文字。');}
watch(draft,()=>{clearTimeout(saveTimer);saveTimer=setTimeout(()=>void saveDraft(),500);});
function cancel(){serial++;request?.abort();busy.value=false;}
async function send(){if(busy.value||!draft.value.trim())return;error.value='';if(!account()){error.value='请先登录 PLEX 学生账号；你的输入和离线语音仍可使用。';return;}stopSpeech();const text=draft.value.trim(),own=++serial,history=messages.value.slice(-18).map(m=>({role:m.role,content:m.content}));request=new AbortController();busy.value=true;messages.value.push({role:'user',content:text});await nextTick();log.value?.scrollTo({top:log.value.scrollHeight});
 try{const value=await plex<{reply:string;source?:string}>('/student/messenger/chat',{message:`当前阅读《星轨编程》：${props.sectionTitle}（${props.sectionId}）。\n我的问题：${text}`,history},'POST',request.signal);if(disposed||own!==serial)return;if(typeof value.reply!=='string'||!value.reply.trim())throw Error('服务端未返回有效答复，请重试');messages.value.push({role:'assistant',content:value.reply,source:['llm','spark','xfyun_agent','llm_stream'].includes(value.source||'')?'在线模型回复':value.source==='rules'||value.source==='rag'?'服务端教学提示（非模型生成）':'服务端回复（来源未标注）'});messages.value=messages.value.slice(-30);if(draft.value.trim()===text)draft.value='';await saveDraft();await nextTick();log.value?.scrollTo({top:log.value.scrollHeight});}
 catch(e){if(own===serial&&!disposed)error.value='消息未完成：'+String(e)+'。输入已保留，可再次发送。';}finally{if(own===serial)busy.value=false;}}
function stopSpeech(){speechSeq++;speechAbort?.abort();speech?.stop();speech=undefined;listening.value=false;partial.value='';volume.value=0;emit('dictating',false);}
async function dictate(){if(listening.value){stopSpeech();voiceStatus.value='语音输入已停止';return;}stopSpeech();error.value='';voiceStatus.value='加载本机中文模型…';listening.value=true;emit('dictating',true);const own=++speechSeq;speechAbort=new AbortController();const abort=speechAbort;lastResult=0;
 try{const {startVoice}=await import('./input-sensors');if(abort.signal.aborted)return;speech=await startVoice('',abort.signal,(text,final,id)=>{if(own!==speechSeq||abort.signal.aborted)return;const cleaned=text.replace(/\s+/g,'').trim();if(!final){partial.value=cleaned;return;}if(id<=lastResult)return;lastResult=id;partial.value='';if(cleaned)draft.value=(draft.value+(draft.value?'\n':'')+cleaned).slice(0,4000);},v=>volume.value=v,e=>{stopSpeech();voiceStatus.value='识别失败：'+String(e);});if(abort.signal.aborted){speech?.stop();return;}voiceStatus.value='正在听 · 说完后稍停，文字会填入输入框';}
 catch(e){if(!abort.signal.aborted){stopSpeech();voiceStatus.value='语音输入未启动：'+String(e);}}
}
function background(){if(document.hidden||!document.hasFocus()){stopSpeech();voiceStatus.value='离开页面后已停止录音；返回可重新开启。';}}
function expired(){cancel();stopSpeech();messages.value=[];error.value='登录失效，请重新登录；当前输入已保留。';}
watch(()=>props.suspended,v=>{if(v)stopSpeech();});
onMounted(async()=>{position.value={x:innerWidth-144,y:innerHeight-250};const p=await getLearning<{x:number;y:number}|undefined>('pet:position',undefined);if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y))position.value=p;const d=await getLearning('pet:draft',{text:''});if(disposed)return;draft.value=typeof d.text==='string'?d.text.slice(0,4000):'';clamp();ready.value=true;window.addEventListener('resize',clamp);window.addEventListener('blur',background);document.addEventListener('visibilitychange',background);window.addEventListener('plex-session-expired',expired);});
const unregister=registerLearningFlush(saveDraft);onBeforeUnmount(()=>{disposed=true;unregister();void saveDraft();cancel();stopSpeech();window.removeEventListener('resize',clamp);window.removeEventListener('blur',background);document.removeEventListener('visibilitychange',background);window.removeEventListener('plex-session-expired',expired);});
defineExpose({open:()=>{if(!opened.value){moved=false;toggle();}}});
</script>
<template><div v-show="ready&&!suspended" class="ebook-pet" :inert="suspended">
 <button ref="pet" class="pet-character" :class="{listening,busy}" :style="{left:position.x+'px',top:position.y+'px'}" aria-label="小艺阅读助手，点击聊天，拖动移动" :aria-expanded="opened" @pointerdown="dragStart" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="dragEnd" @click="toggle" @keydown.stop="petKey"><img src="/brand/little-e-front.png" alt="小艺正面机器人" draggable="false"/><span>{{listening?'正在听…':busy?'思考中…':'小艺 · 点我聊聊'}}</span></button>
 <section v-if="opened" class="pet-bubble" :style="bubble" role="dialog" aria-label="小艺聊天气泡" @keydown.esc.stop.prevent="close" @keydown.stop>
 <div class="pet-bubble-heading"><div><strong>小艺 <small>PLEX 小E</small></strong><span>陪你读懂这一页</span></div><button aria-label="关闭聊天气泡" @click="close">×</button></div>
 <p class="pet-context">当前：{{sectionTitle}} <button v-if="!account()" @click="close();emit('login')">登录 PLEX</button></p>
 <div ref="log" class="pet-messages" role="log" aria-label="小艺对话记录" aria-live="polite"><p v-if="!messages.length" class="pet-welcome">有什么没想明白的，直接告诉我。也可以点麦克风，把问题说出来。<small>语音在本机转为文字；点击发送后，问题、当前章节和最近对话才会交给 PLEX。</small></p><article v-for="(m,i) in messages" :key="i" :class="m.role"><small>{{m.role==='user'?'你':m.source}}</small><p>{{m.content}}</p></article><p v-if="busy" role="status">正在等待 PLEX 回复…</p></div>
 <p v-if="error" class="pet-error" role="alert">{{error}}</p><div class="pet-compose"><label class="pet-label" for="pet-message">发消息给小艺</label><textarea id="pet-message" ref="input" v-model="draft" maxlength="4000" placeholder="输入问题，或点击语音输入…" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send"/><p v-if="partial" class="pet-partial">识别中：{{partial}}</p><p v-if="voiceStatus" class="pet-voice-status" role="status">{{voiceStatus}}</p><meter v-if="listening" :value="volume" min="0" max="0.3" aria-label="语音输入音量"/><div class="pet-actions"><button :disabled="busy" @click="dictate">{{listening?'停止录音':'语音输入'}}</button><button v-if="busy" @click="cancel">停止等待</button><button :disabled="busy||!draft.trim()" @click="send">发送</button></div><small>Ctrl / ⌘ + Enter 发送 · 语音不会自动发送</small></div>
 </section></div></template>
<style>
.pet-character{display:flex;flex-direction:column;align-items:center;position:fixed;z-index:690;width:104px;height:148px;background:transparent;border:0;touch-action:none;cursor:grab;padding:0;user-select:none}.pet-character:active{cursor:grabbing}.pet-character img{flex-shrink:0;width:100%;height:126px;object-fit:contain;filter:drop-shadow(0 8px 6px #0008);animation:pet-breathe 3.4s ease-in-out infinite;pointer-events:none;transform-origin:center bottom}.pet-character:hover img{animation:pet-greet .7s ease-in-out infinite alternate}.pet-character.listening img,.pet-character.busy img{animation:pet-greet .9s ease-in-out infinite alternate}.pet-character span{display:block;background:#102f42e8;color:#ceeff9;border:1px solid #5bb9cf;border-radius:20px;font-size:10px;padding:4px;white-space:nowrap}.pet-bubble{position:fixed;z-index:700;width:min(380px,calc(100vw - 16px));max-height:calc(100dvh - 16px);height:520px;display:flex;flex-direction:column;background:#10283b;color:#e7f6fc;border:2px solid #73c7dd;border-radius:18px;box-shadow:0 16px 70px #0009;overflow:hidden}.pet-bubble .pet-bubble-heading{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#194158}.pet-bubble .pet-bubble-heading div{display:flex;flex-direction:column;gap:3px}.pet-bubble .pet-bubble-heading small,.pet-bubble .pet-bubble-heading span{font-size:11px;color:#b7dce9}.reader .pet-bubble button{transition:none;font:inherit;font-size:12px;padding:7px 12px;color:#e9f9ff;background:#1b455c;border:1px solid #78a9be;border-radius:7px}.pet-bubble .pet-bubble-heading>button{font-size:20px;line-height:1}.pet-context{font-size:11px;margin:8px 14px;color:#c2d8e3}.pet-messages{overflow:auto;overscroll-behavior:contain;min-height:72px;flex:1;padding:6px 14px}.pet-welcome{font-size:13px;line-height:1.8}.pet-welcome small{display:block;color:#b0ccd8;font-size:11px;margin-top:8px}.pet-messages article{border-radius:9px;background:#173c51;padding:9px 12px;margin:8px 14px 8px 0}.pet-messages article.user{background:#245164;margin:8px 0 8px 20px}.pet-messages article small{font-size:10px;color:#9fe5f1}.pet-messages article p{font-size:13px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin:4px 0}.pet-compose{padding:10px 14px;border-top:1px solid #365c71;overflow:auto;flex-shrink:0;max-height:50%}.pet-label{display:block;font-size:11px;margin-bottom:5px}.pet-compose textarea{width:100%;min-height:64px;max-height:140px;resize:vertical;border:1px solid #6b98ac;border-radius:7px;background:#0b1e2f;color:#effaff;font:inherit;font-size:13px;padding:9px}.pet-actions{display:flex;gap:8px;justify-content:space-between;margin:8px 0}.reader .pet-bubble .pet-actions button:last-child,.reader .pet-bubble .pet-actions button:last-child:hover{background:#96e1ee;color:#092333;font-weight:700}.pet-bubble button:disabled{opacity:.5}.pet-compose>small,.pet-partial,.pet-voice-status{font-size:10px;color:#bed5e0;margin:5px 0}.pet-error{font-size:12px;line-height:1.5;color:#ffca9f;padding:8px 14px;margin:0;max-height:92px;overflow:auto}.ebook-pet :focus-visible{outline:3px solid #ffe48f;outline-offset:2px}@keyframes pet-breathe{50%{transform:translateY(-5px) rotate(1deg)}}@keyframes pet-greet{to{transform:translateY(-5px) rotate(-4deg)}}@media(prefers-reduced-motion:reduce){.pet-character img,.pet-character:hover img,.pet-character.listening img,.pet-character.busy img{animation:none}}
</style>
